fn frame(t: i32) {
    let notes = [262, 294, 330, 349, 392, 440, 494, 523];
    let idx: i32 = (t / 15) % 8;
    if t % 15 == 0 {
        host::audio::tone(notes[idx], 130, 0);
    }
    host::display::clear(0x101018);
    host::display::draw_string(8, 8, "C MAJOR LOOP", 0xffffff, 2);
    host::display::draw_number(8, 40, notes[idx], 0x00ffaa, 2);
    let mut i: i32 = 0;
    while i < 8 {
        let mut c: i32 = 0x303038;
        if i == idx { c = 0x00ffaa; }
        host::display::fill_rect(8 + i * 62, 300, 54, 120, c);
        i = i + 1;
    }
    host::display::present();
}
